#!/usr/bin/env python3
"""List the unpacked document tree for inspection."""
import os

for root, dirs, files in os.walk('unpacked_report'):
    level = root.replace('unpacked_report', '').count(os.sep)
    indent = '  ' * level
    print(f'{indent}{os.path.basename(root)}/')
    for f in sorted(files):
        print(f'{indent}  {f}')

